public class ArrayRunner {interface Task{Object run();}static void run(String n,int m,Task t){ArraySupport.mode=m;ArraySupport.trace=0;try{System.out.println(n+m+":"+t.run()+":"+ArraySupport.trace);}catch(RuntimeException e){System.out.println(n+m+":"+e.getClass().getName()+":"+(e==ArraySupport.FAILURE)+":"+ArraySupport.trace);}}public static void main(String[]args){for(int m=0;m<2;m++){run("ints2",m,()->DeferredArrays.ints(2).length);run("intsNegative",m,()->DeferredArrays.ints(-1).length);run("refs2",m,()->DeferredArrays.refs(2).length);run("refsNegative",m,()->DeferredArrays.refs(-1).length);run("multi2",m,()->DeferredArrays.multi(2,3)[0].length);run("multiNegative",m,()->DeferredArrays.multi(2,-1).length);}}}
